#[derive(Debug)]
struct ToolsRequestEndpoint { provider: Rc<dyn ToolsProvider> }

#[derive(Debug)]
pub struct ToolsEndpoint<P: ToolsProvider> { provider: Rc<P>, request_endpoint: ToolsRequestEndpoint }
impl<P: ToolsProvider> ToolsEndpoint<P> {
    pub fn new(provider: P) -> Self {
        let provider = Rc::new(provider);
        let request_provider: Rc<dyn ToolsProvider> = provider.clone();
        Self { provider, request_endpoint: ToolsRequestEndpoint { provider: request_provider } }
    }
}

impl<P: ToolsProvider> NativeRequestEndpoint for ToolsEndpoint<P> {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }
    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }
    fn operations(&self) -> &'static [&'static str] { &[
        CATALOG_OPERATION,
        EXECUTE_OPERATION,
    ] }
    fn typed_endpoint(&self) -> Option<&dyn std::any::Any> { Some(&self.request_endpoint) }
    fn invoke(&self, operation: &str, request: Box<dyn std::any::Any>, context: InvocationContext) -> LocalBoxFuture<'static, Result<Result<Box<dyn std::any::Any>, Box<dyn std::any::Any>>, RuntimeFailure>> {
        match operation {
            CATALOG_OPERATION => {
                let Ok(request) = request.downcast::<CatalogRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let invocation = Rc::clone(&self.provider).catalog(context, *request);
                Box::pin(async move {
                    invocation.await.map(|result| {
                        result
                            .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                            .map_err(|error| Box::new(error) as Box<dyn std::any::Any>)
                    })
                })
            },
            EXECUTE_OPERATION => {
                let Ok(request) = request.downcast::<ExecuteRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let invocation = Rc::clone(&self.provider).execute(context, *request);
                Box::pin(async move {
                    invocation.await.map(|result| {
                        result
                            .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                            .map_err(|error| Box::new(error) as Box<dyn std::any::Any>)
                    })
                })
            }
            _ => Box::pin(futures::future::ready(Err(RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }))),
        }
    }
}

impl<P: ToolsProvider> NativeStreamEndpoint for ToolsEndpoint<P> {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }
    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }
    fn operations(&self) -> &'static [&'static str] { &[
        EXECUTE_STREAM_OPERATION,
    ] }
    fn open(&self, operation: &str, request: Box<dyn std::any::Any>, context: InvocationContext) -> LocalBoxFuture<'static, Result<Result<Box<dyn NativeStreamSession>, Box<dyn std::any::Any>>, RuntimeFailure>> {
        match operation {
            EXECUTE_STREAM_OPERATION => {
                let Ok(request) = request.downcast::<ExecuteStreamRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let provider = Rc::clone(&self.provider);
                Box::pin(async move {
                    match provider.execute_stream(context, *request).await {
                        Ok(value) => Ok(Ok(value as Box<dyn NativeStreamSession>)),
                        Err(ToolsExecuteStreamInvocationError::Domain(error)) => Ok(Err(Box::new(error) as Box<dyn std::any::Any>)),
                        Err(ToolsExecuteStreamInvocationError::Runtime(error)) => Err(error),
                    }
                })
            }
            _ => Box::pin(futures::future::ready(Err(RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }))),
        }
    }
}

#[doc(hidden)]
#[macro_export]
macro_rules! __lenso_native_endpoints_tools {
    ($provider:expr, $support:path) => {{
        use $support as __LensoNativeSupport;
        let endpoint = ::std::rc::Rc::new($crate::ToolsEndpoint::new($provider));
        (
            vec![endpoint.clone() as ::std::rc::Rc<dyn __LensoNativeSupport::NativeRequestEndpoint>],
            vec![endpoint.clone() as ::std::rc::Rc<dyn __LensoNativeSupport::NativeStreamEndpoint>],
            vec![],
        )
    }};
}

#[doc(hidden)]
#[macro_export]
macro_rules! __lenso_native_provide_tools {
    ($provider:expr, $lifecycle:expr, $support:path) => {{
        use $support as __LensoNativeSupport;
        let (request_endpoints, stream_endpoints, event_endpoints) =
            $crate::__lenso_native_endpoints_tools!($provider, $support);
        __LensoNativeSupport::NativeModuleInstance::with_all_endpoints(
            request_endpoints,
            stream_endpoints,
            event_endpoints,
            $lifecycle,
        )
    }};
}

#[derive(Debug)]
pub struct ToolsClient {
    catalog: NativeRequestHandle<ToolsCatalog>,
    execute: NativeRequestHandle<ToolsExecute>,
    execute_stream: NativeStreamHandle<ToolsExecuteStream>,
}
impl ToolsClient {
    pub fn from_dependencies(dependencies: &ModuleDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub async fn catalog(&self, request: CatalogRequest) -> Result<CatalogResponse, ToolsCatalogInvocationError> {
        self.catalog.invoke(CATALOG_OPERATION, request).await
            .map_err(ToolsCatalogInvocationError::Runtime)?
            .map_err(ToolsCatalogInvocationError::Domain)
    }

    pub async fn catalog_with_context(&self, context: InvocationContext, request: CatalogRequest) -> Result<CatalogResponse, ToolsCatalogInvocationError> {
        self.catalog.invoke_with_context(CATALOG_OPERATION, context, request).await
            .map_err(ToolsCatalogInvocationError::Runtime)?
            .map_err(ToolsCatalogInvocationError::Domain)
    }

    pub async fn execute(&self, request: ExecuteRequest) -> Result<ExecuteResponse, ToolsExecuteInvocationError> {
        self.execute.invoke(EXECUTE_OPERATION, request).await
            .map_err(ToolsExecuteInvocationError::Runtime)?
            .map_err(ToolsExecuteInvocationError::Domain)
    }

    pub async fn execute_with_context(&self, context: InvocationContext, request: ExecuteRequest) -> Result<ExecuteResponse, ToolsExecuteInvocationError> {
        self.execute.invoke_with_context(EXECUTE_OPERATION, context, request).await
            .map_err(ToolsExecuteInvocationError::Runtime)?
            .map_err(ToolsExecuteInvocationError::Domain)
    }

    pub async fn execute_stream(&self, request: ExecuteStreamRequest) -> Result<NativeStream<ToolsExecuteStream>, ToolsExecuteStreamInvocationError> {
        self.execute_stream.open(EXECUTE_STREAM_OPERATION, request).await
            .map_err(ToolsExecuteStreamInvocationError::Runtime)?
            .map_err(ToolsExecuteStreamInvocationError::Domain)
    }

    pub async fn execute_stream_with_context(&self, context: InvocationContext, request: ExecuteStreamRequest) -> Result<NativeStream<ToolsExecuteStream>, ToolsExecuteStreamInvocationError> {
        self.execute_stream.open_with_context(EXECUTE_STREAM_OPERATION, context, request).await
            .map_err(ToolsExecuteStreamInvocationError::Runtime)?
            .map_err(ToolsExecuteStreamInvocationError::Domain)
    }
}

impl CapabilityClient for ToolsClient {
    type Dependencies = ModuleDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &ModuleDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            catalog: dependencies.one::<ToolsCatalog>()?,
            execute: dependencies.one::<ToolsExecute>()?,
            execute_stream: dependencies.one_stream::<ToolsExecuteStream>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::ModuleFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for ToolsClient {
    fn many_from_dependencies(
        dependencies: &ModuleDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    catalog: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ToolsCatalog>()?,
                    execute: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ToolsExecute>()?,
                    execute_stream: binding.stream_handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ToolsExecuteStream>()?,
                    },
                ))
            })
            .collect()
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum ToolsCatalogInvocationError {
    Domain(CatalogError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum ToolsExecuteInvocationError {
    Domain(ExecuteError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum ToolsExecuteStreamInvocationError {
    Domain(ExecuteStreamError),
    Runtime(RuntimeFailure),
}

#[derive(Clone, Copy, Debug)]
pub struct ToolsGuestClient<'a, H: lenso_guest_sdk::HostImports> {
    capability: lenso_guest_sdk::GuestCapability<'a, H>,
}

impl<'a, H: lenso_guest_sdk::HostImports> ToolsGuestClient<'a, H> {
    pub fn from_context(context: &'a lenso_guest_sdk::GuestContext<H>) -> Result<Self, lenso_guest_sdk::GuestError<serde_json::Value>> {
        context
            .require(CAPABILITY_ID, DESCRIPTOR_VERSION, &[CATALOG_OPERATION, EXECUTE_OPERATION], &[EXECUTE_STREAM_OPERATION])
            .map(|capability| Self { capability })
    }

    pub fn catalog(&self, request: &CatalogRequest) -> Result<CatalogResponse, lenso_guest_sdk::GuestError<CatalogError>> {
        self.capability.request(CATALOG_OPERATION, request)
    }

    pub fn execute(&self, request: &ExecuteRequest) -> Result<ExecuteResponse, lenso_guest_sdk::GuestError<ExecuteError>> {
        self.capability.request(EXECUTE_OPERATION, request)
    }

    pub fn execute_stream(&self, request: &ExecuteStreamRequest) -> Result<lenso_guest_sdk::GuestStream<H, ExecuteStreamResponse, ExecuteStreamError>, lenso_guest_sdk::GuestError<ExecuteStreamError>> {
        self.capability.open_stream(EXECUTE_STREAM_OPERATION, request)
    }
}

#[derive(Debug, Default)]
pub struct ToolsJsonCodec;

impl lenso_runtime_codec::JsonCapabilityCodec for ToolsJsonCodec {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }

    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }

    fn request_operations(&self) -> &'static [&'static str] { &[CATALOG_OPERATION, EXECUTE_OPERATION] }
    fn stream_operations(&self) -> &'static [&'static str] { &[EXECUTE_STREAM_OPERATION] }

    fn encode_request(&self, operation: &str, request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            CATALOG_OPERATION => {
                let value = request.downcast_ref::<CatalogRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            EXECUTE_OPERATION => {
                let value = request.downcast_ref::<ExecuteRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_response(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            CATALOG_OPERATION => serde_json::from_value::<CatalogResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            EXECUTE_OPERATION => serde_json::from_value::<ExecuteResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_domain_error(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            CATALOG_OPERATION => serde_json::from_value::<CatalogError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            EXECUTE_OPERATION => serde_json::from_value::<ExecuteError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_stream_open(&self, operation: &str, request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            EXECUTE_STREAM_OPERATION => {
                let value = request.downcast_ref::<ExecuteStreamRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_stream_message(&self, operation: &str, message: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            EXECUTE_STREAM_OPERATION => {
                let value = message.downcast_ref::<ExecuteStreamResponse>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_stream_message(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            EXECUTE_STREAM_OPERATION => serde_json::from_value::<ExecuteStreamResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_stream_domain_error(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            EXECUTE_STREAM_OPERATION => serde_json::from_value::<ExecuteStreamError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn invoke_host_request(&self, dependency: lenso_kernel::ModuleDependencyHandle, operation: String, request: serde_json::Value, context: InvocationContext) -> lenso_runtime_codec::JsonHostRequestFuture {
        match operation.as_str() {
            CATALOG_OPERATION => {
                let request = serde_json::from_value::<CatalogRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<ToolsCatalog>()?;
                    match handle.invoke_with_context(CATALOG_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            EXECUTE_OPERATION => {
                let request = serde_json::from_value::<ExecuteRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<ToolsExecute>()?;
                    match handle.invoke_with_context(EXECUTE_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            _ => Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation)))),
        }
    }

    fn open_host_stream(&self, dependency: lenso_kernel::ModuleStreamDependencyHandle, operation: String, request: serde_json::Value, context: InvocationContext) -> lenso_runtime_codec::JsonHostStreamOpenFuture {
        match operation.as_str() {
            EXECUTE_STREAM_OPERATION => {
                let request = serde_json::from_value::<ExecuteStreamRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<ToolsExecuteStream>()?;
                    match handle.open_with_context(EXECUTE_STREAM_OPERATION, context, request).await? {
                        Ok(stream) => Ok(Ok(lenso_runtime_codec::json_host_stream::<ToolsExecuteStream>(
                            stream,
                            |value| serde_json::from_value::<ExecuteStreamResponse>(value).map_err(|_| runtime_codec_protocol_failure()),
                            |message| serde_json::to_value(message).map_err(|_| runtime_codec_protocol_failure()),
                            |error| serde_json::to_value(error).map_err(|_| runtime_codec_protocol_failure()),
                        ))),
                        Err(error) => serde_json::to_value(error)
                            .map(Err)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            _ => Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation)))),
        }
    }
}

fn runtime_codec_protocol_failure() -> RuntimeFailure { RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID } }

fn runtime_codec_unknown_operation(operation: &str) -> RuntimeFailure {
    RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }
}
